
'use strict';
const LESSONS=[
{id:'historia',mod:'15',grp:'A',icon:'🧭',title:'História do magnetismo',desc:'Ímãs, bússola, Oersted, Ampère, Faraday e Maxwell.',min:7,tag:'Fundamentos',macete:'Oersted: eletricidade cria campo magnético. Faraday: fluxo magnético variando cria corrente induzida.',trap:'Um ímã parado perto de uma espira parada não gera corrente contínua por indução. É necessária mudança de fluxo.',body:`<p>O magnetismo era conhecido pela atração exercida pela <strong>magnetita</strong> sobre o ferro. O estudo da bússola mostrou que a Terra se comporta aproximadamente como um enorme ímã, com campo magnético próprio.</p><h3>O que cai em nomes e descobertas?</h3><div class="tablewrap"><table><tr><th>Cientista / ideia</th><th>O que recordar</th></tr><tr><td>William Gilbert</td><td>Estudou ímãs e descreveu a Terra como um grande ímã.</td></tr><tr><td>Ørsted (1820)</td><td>Mostrou que uma corrente elétrica desvia a agulha da bússola: corrente cria campo magnético.</td></tr><tr><td>Ampère</td><td>Investigou as forças entre correntes e as relações entre corrente elétrica e magnetismo.</td></tr><tr><td>Faraday (1831)</td><td>Demonstrou a indução eletromagnética: variações de fluxo magnético geram fem induzida.</td></tr><tr><td>Maxwell</td><td>Unificou a descrição dos fenômenos elétricos e magnéticos em equações.</td></tr></table></div><h3>Ímãs e campos magnéticos</h3><p>Um ímã tem <strong>polo norte e polo sul</strong>. Polos iguais se repelem; polos diferentes se atraem. Fora do ímã, as linhas do campo magnético vão do polo norte para o sul e formam linhas fechadas ao continuar pelo interior.</p><div class="note"><b>💡 Macete</b>Quebrar um ímã não produz um polo norte isolado. Cada pedaço continua com norte e sul.</div>`,q:{q:'Quem demonstrou que uma corrente elétrica produz campo magnético, desviando uma bússola?',o:['Faraday','Ørsted','Newton','Huygens'],a:1,e:'Ørsted observou o efeito da corrente elétrica sobre a bússola em 1820.'}},
{id:'corrente',mod:'16',grp:'A',icon:'🧲',title:'Corrente produz campo magnético',desc:'Fio retilíneo, espira, solenoide e regra da mão direita.',min:12,tag:'Campo B',macete:'Polegar da mão direita aponta no sentido da corrente convencional; dedos curvados mostram o sentido do campo em torno do fio.',trap:'Se duplicar a distância a um fio longo, B cai pela metade; se duplicar a corrente, B dobra.',body:`<p>Uma corrente elétrica gera um <strong>campo magnético B</strong>. A unidade de B é o tesla (T). O campo circula em torno de um fio longo retilíneo.</p><h3>Fio retilíneo muito longo</h3><div class="formula">B = μ₀ · I / (2πr)</div><p><strong>I</strong> é a corrente (A), <strong>r</strong> é a distância ao fio (m), e <strong>μ₀ = 4π × 10⁻⁷ T·m/A</strong> no vácuo.</p><div class="example"><strong>Exemplo resolvido</strong><p>Um fio conduz I = 5 A. A 10 cm = 0,10 m, o campo é:</p><div class="formula">B = 2 × 10⁻⁷ × (5 / 0,10) = 1 × 10⁻⁵ T = 10 μT</div></div><h3>Regra da mão direita</h3><p>Segura o fio com a <strong>mão direita</strong>. O polegar aponta no sentido da corrente convencional; os dedos enrolados indicam o sentido do campo magnético. Símbolo <strong>⊙</strong> = vetor saindo do papel; <strong>⊗</strong> = entrando no papel.</p><h3>Outras geometrias</h3><div class="tablewrap"><table><tr><th>Geometria</th><th>Expressão idealizada</th></tr><tr><td>Centro de uma espira circular</td><td>B = μ₀I / (2R)</td></tr><tr><td>Centro de N espiras iguais</td><td>B = μ₀NI / (2R)</td></tr><tr><td>Interior de solenoide longo</td><td>B ≈ μ₀ n I, n = N/L</td></tr></table></div><div class="note"><b>💡 Em prova</b>Fio longo: B proporcional a I e inversamente proporcional à distância r. Duplicou r, B cai pela metade.</div>`,q:{q:'Num fio longo, se a corrente dobra e a distância ao fio permanece fixa, o campo magnético:',o:['Cai pela metade','Fica igual','Dobra','Quadruplica'],a:2,e:'Pela expressão B = μ₀I/(2πr), o campo é diretamente proporcional à corrente.'}},
{id:'forca',mod:'17',grp:'A',icon:'⚡',title:'Força magnética',desc:'Carga em movimento, fio com corrente e ângulo entre vetores.',min:11,tag:'Força',macete:'A força é máxima a 90° e nula a 0°/180°. O seno do ângulo resolve essa pegadinha.',trap:'Uma carga parada num campo magnético estático não sofre força magnética. O sinal da carga altera o sentido, não o módulo.',body:`<p>Uma carga elétrica em movimento pode sofrer uma força ao atravessar um campo magnético. A força é perpendicular tanto à velocidade quanto ao campo.</p><h3>Carga em movimento</h3><div class="formula">F = |q| · v · B · sen θ</div><p><strong>|q|</strong> é o módulo da carga (C); <strong>v</strong>, a velocidade (m/s); <strong>B</strong>, o campo (T); <strong>θ</strong>, o ângulo entre a velocidade e B.</p><div class="tablewrap"><table><tr><th>Ângulo</th><th>sen θ</th><th>Força</th></tr><tr><td>0° ou 180°</td><td>0</td><td>Zero</td></tr><tr><td>30°</td><td>0,5</td><td>Metade de |q|vB</td></tr><tr><td>90°</td><td>1</td><td>Máxima</td></tr></table></div><div class="example"><strong>Exemplo resolvido</strong><p>Uma carga com |q| = 2 × 10⁻⁶ C move-se a v = 10³ m/s, perpendicularmente a B = 0,5 T.</p><div class="formula">F = 2 × 10⁻⁶ × 10³ × 0,5 × 1 = 10⁻³ N</div></div><h3>Força em um fio retilíneo</h3><div class="formula">F = B · I · L · sen θ</div><p>O fio precisa estar imerso no campo; L é o comprimento de fio que está nele. Para carga positiva, use a mão direita na direção de v × B; para carga negativa, inverta o sentido.</p><h3>Movimento circular</h3><p>Se v é perpendicular a B num campo uniforme, a força pode atuar como centrípeta: <strong>R = mv/(|q|B)</strong>. Ela altera a direção da velocidade, não o módulo, pois força magnética não realiza trabalho sobre uma carga pontual.</p>`,q:{q:'Uma carga entra paralelamente às linhas de um campo magnético uniforme. A força magnética vale:',o:['O máximo possível','Zero','qvB/2','O dobro de qvB'],a:1,e:'Como θ = 0°, sen(0°) = 0 e F = |q|vB sen θ = 0.'}},
{id:'inducao',mod:'18',grp:'A',icon:'🌀',title:'Indução eletromagnética',desc:'Fluxo magnético, leis de Faraday e Lenz, geradores.',min:13,tag:'Indução',macete:'Não é ter campo magnético que induz corrente: é MUDAR o fluxo. Lenz: a corrente induzida combate a mudança no fluxo.',trap:'O ângulo θ no fluxo é medido em relação à NORMAL (perpendicular) da superfície, não ao plano dela.',body:`<p>Quando o <strong>fluxo magnético</strong> através de uma espira muda, aparece uma força eletromotriz induzida (fem). Se o circuito estiver fechado, pode circular corrente.</p><h3>Fluxo magnético</h3><div class="formula">Φ = B · A · cos θ</div><p><strong>A</strong> é a área em m², <strong>B</strong> em tesla, e θ é o ângulo entre B e a <strong>normal</strong> à área. A unidade é weber (Wb).</p><h3>Lei de Faraday</h3><div class="formula">ε = −N · ΔΦ / Δt</div><p><strong>N</strong> é o número de espiras. O sinal negativo é explicado pela <strong>lei de Lenz</strong>: a fem induzida tende a produzir uma corrente cujo campo se opõe à variação do fluxo.</p><div class="example"><strong>Exemplo resolvido</strong><p>Uma bobina de 20 espiras tem fluxo de 0,03 Wb por espira que cai para 0,01 Wb em 0,2 s.</p><div class="formula">|ε| = 20 × |0,01 − 0,03| / 0,2 = 2 V</div></div><h3>Entendendo Lenz</h3><p>Se o fluxo que <strong>entra</strong> na página aumenta, a bobina tenta criar campo <strong>saindo</strong> da página. Se o fluxo entrando diminui, a bobina tenta manter o fluxo entrando. Atenção: ela se opõe à <em>mudança</em>, não obrigatoriamente ao campo original.</p><div class="note"><b>💡 Geradores e transformadores</b>Gerador usa movimento para variar fluxo e obter fem. Transformador ideal alimentado com corrente alternada: V₁/V₂ = N₁/N₂.</div>`,q:{q:'Uma espira parada sob um campo magnético uniforme e constante sofre indução de fem?',o:['Sim, sempre','Só por existir B','Não, porque o fluxo não varia','Sim, mas apenas no vácuo'],a:2,e:'Para haver fem induzida é necessário que o fluxo magnético varie com o tempo.'}},
{id:'espelhos',mod:'08',grp:'B',icon:'🪞',title:'Espelhos esféricos',desc:'Côncavo, convexo, foco, imagens e equação dos espelhos.',min:14,tag:'Óptica',macete:'Convexo SEMPRE dá imagem virtual, direita e menor. Côncavo depende de onde o objeto está em relação ao foco F e ao centro C.',trap:'Côncavo não forma sempre imagem maior. Além do centro C ela é real, invertida e menor. Lembre f = R/2.',body:`<p>Espelhos esféricos são superfícies refletoras que correspondem a parte de uma esfera. No <strong>côncavo</strong>, a face refletora fica voltada para dentro; no <strong>convexo</strong>, para fora.</p><h3>Pontos importantes</h3><div class="tablewrap"><table><tr><th>Símbolo</th><th>Significado</th></tr><tr><td>V</td><td>Vértice do espelho</td></tr><tr><td>F</td><td>Foco principal</td></tr><tr><td>C</td><td>Centro de curvatura</td></tr><tr><td>R</td><td>Raio de curvatura</td></tr></table></div><div class="formula">f = R/2</div><p>Para espelhos de pequena abertura (aproximação paraxial), usamos a <strong>equação de Gauss</strong>:</p><div class="formula">1/f = 1/p + 1/p′</div><p><strong>p</strong> é a distância do objeto e <strong>p′</strong> é a distância da imagem. Nesta convenção: f &gt; 0 para côncavo, f &lt; 0 para convexo; p′ &gt; 0 para imagem real e p′ &lt; 0 para virtual.</p><div class="formula">Aumento = h′/h = −p′/p</div><h3>Como o côncavo se comporta?</h3><div class="tablewrap"><table><tr><th>Objeto</th><th>Imagem</th></tr><tr><td>Além de C</td><td>Real, invertida, menor; entre C e F</td></tr><tr><td>Em C</td><td>Real, invertida, mesmo tamanho; em C</td></tr><tr><td>Entre C e F</td><td>Real, invertida, maior; além de C</td></tr><tr><td>Em F</td><td>No infinito (raios refletidos paralelos)</td></tr><tr><td>Entre F e V</td><td>Virtual, direita, maior; atrás do espelho</td></tr></table></div><div class="note"><b>💡 Espelho convexo</b>Para qualquer objeto real em frente a um convexo, a imagem é virtual, direita e menor. Por isso ele é usado em retrovisores com maior campo de visão.</div><div class="example"><strong>Exemplo resolvido</strong><p>Espelho côncavo f = 20 cm, objeto p = 60 cm. A imagem fica em p′ = fp/(p − f) = 20×60/40 = 30 cm.</p><p>O aumento é A = −30/60 = −0,5. Portanto, a imagem é <strong>real, invertida e metade do tamanho</strong>.</p></div>`,q:{q:'Em qualquer posição de um objeto real diante de espelho convexo, a imagem é:',o:['Real e maior','Virtual, direita e menor','Real e invertida','Virtual e invertida'],a:1,e:'O espelho convexo produz sempre imagem virtual, direita e reduzida para objetos reais.'}}
];
const FORMULAS=[['Fio retilíneo longo','B = μ₀I/(2πr)','B em T, I em A, r em m.'],['Espira circular (centro)','B = μ₀I/(2R)','Se houver N voltas, multiplique por N.'],['Solenoide longo','B ≈ μ₀(N/L)I','Aproximação para seu interior.'],['Carga em campo magnético','F = |q|vB·sen θ','θ entre v e B.'],['Fio em campo magnético','F = BIL·sen θ','L é o trecho imerso no campo.'],['Raio da trajetória circular','R = mv/(|q|B)','Quando v é perpendicular ao campo B.'],['Fluxo magnético','Φ = BA·cos θ','θ entre B e a normal à superfície.'],['Lei de Faraday','|ε| = N|ΔΦ|/Δt','Módulo da fem média em V.'],['Espelhos: distância focal','f = R/2','Aproximação paraxial.'],['Equação dos espelhos','1/f = 1/p + 1/p′','p′ real positivo; virtual negativo.'],['Aumento da imagem','A = −p′/p','A < 0: invertida. A > 0: direita.']];
